WITH matrix AS (
  SELECT * FROM read_csv_auto('r1/reports/data/performance-matrix.csv', header = true)
)
SELECT * FROM matrix ORDER BY context_target, concurrency;

WITH matrix AS (
  SELECT * FROM read_csv_auto('r1/reports/data/performance-matrix.csv', header = true)
)
SELECT COUNT(*) AS planned_cells, COUNT(*) FILTER (WHERE status <> 'pending') AS executed_cells, COUNT(*) FILTER (WHERE status = 'complete') AS complete_cells, COUNT(*) FILTER (WHERE status = 'failed') AS failed_cells, COUNT(*) FILTER (WHERE status = 'pending') AS pending_cells FROM matrix;

WITH matrix AS (
  SELECT * FROM read_csv_auto('r1/reports/data/performance-matrix.csv', header = true)
)
SELECT context_target / 1000 AS context_k, COUNT(*) FILTER (WHERE status = 'complete') AS complete, COUNT(*) FILTER (WHERE status = 'failed') AS failed, COUNT(*) FILTER (WHERE status = 'pending') AS pending FROM matrix GROUP BY context_target ORDER BY context_target;

